{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "AZD3759, a close anilino-heterocyclic kinase inhibitor with methoxy/fluoro and amine-amide solubilizing features, reached distribution equilibrium across rats, mice, and monkeys with Kpuu,brain and Kpuu,CSF > 0.5, demonstrating robust CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "A structurally related methoxy-substituted anilino-heterocycle with a morpholine-containing substituent showed good brain and CSF penetration (Kpuu,brain 0.47, Kpuu,CSF 0.76), supporting meaningful CNS access for the query's similar morpholine amide and methoxy/fluoro pattern.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "A pyrimidine-aniline analogue bearing a morpholine/piperazine amide-type solubilizing group achieved a brain/plasma ratio of 100%, directly supporting the CNS-penetrant potential of the query's pyrimidine-aniline-morpholine scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "BLU-451, a CNS-penetrant anilino-pyrimidine inhibitor with a trifluoromethyl-substituted aromatic group, showed a brain-plasma ratio of 0.62 in intracranial xenograft models, supporting that the query's CF3-containing pyrimidine aniline can still penetrate the BBB meaningfully.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues demonstrate meaningful CNS penetration via direct brain/plasma, Kpuu, CSF, or PET evidence, and the query shares the key anilino-heterocycle, methoxy/fluoro, and morpholine-amide features associated with those positive results. No contradictory evidence was identified.",
  "evidence_gaps": [
    "No direct brain/plasma or Kpuu measurement exists for the exact query molecule.",
    "Efflux-transporter status (P-gp/BCRP) was not explicitly measured for the query, though several close analogues show good unbound brain partitioning.",
    "The influence of the cyclopropylamino and CF3 groups on CNS exposure is inferred from analogues rather than directly measured."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

